"""Tunjukkan letak persis perbedaan chunk dan pertanyaan dibanding acuan panduan.

Jalankan dari folder utama project:  python cek_detail.py
"""
import base64
import json
import zlib

ACUAN = json.loads(zlib.decompress(base64.b64decode(
    ""
)))


def beda_teks(a: str, b: str, lebar: int = 12) -> str:
    """Potongan teks di sekitar kata pertama yang berbeda."""
    ka, kb = a.split(), b.split()
    i = next((i for i, (x, y) in enumerate(zip(ka, kb)) if x != y), min(len(ka), len(kb)))
    mulai = max(0, i - lebar)
    return ("    acuan  : ... " + " ".join(ka[mulai:i + lebar]) + " ...\n"
            "    punyamu: ... " + " ".join(kb[mulai:i + lebar]) + " ...")


if __name__ == "__main__":
    punyaku = {}
    for baris in open("data/chunks.jsonl", encoding="utf-8"):
        c = json.loads(baris)
        punyaku[c["id"]] = c
    ditampilkan = 0
    for cid, acuan in ACUAN["chunks"].items():
        c = punyaku.get(cid)
        if c is None:
            print(f"[{cid}] tidak ada di chunks.jsonl-mu")
            continue
        kolom = [k for k in acuan if acuan[k] != c.get(k)]
        if not kolom:
            continue
        print(f"[{cid}] bagian {acuan['bagian']} | kolom beda: {kolom}")
        for k in kolom:
            if k == "teks" and ditampilkan < 8:
                print(beda_teks(acuan["teks"], c["teks"]))
                ditampilkan += 1
            elif k != "teks":
                print(f"    {k}: acuan={acuan[k]!r} | punyamu={c.get(k)!r}")
    no_acuan = {cid.split("-")[0] for cid in ACUAN["chunks"]}
    for cid in punyaku:
        if cid.split("-")[0] in no_acuan and cid not in ACUAN["chunks"]:
            print(f"[{cid}] ada di punyamu tetapi tidak ada di acuan")

    print()
    soal = {}
    for baris in open("eval/questions.jsonl", encoding="utf-8"):
        q = json.loads(baris)
        soal[q["id"]] = q
    for qid, acuan in ACUAN["questions"].items():
        q = soal.get(qid, {})
        for k in acuan:
            if acuan[k] != q.get(k):
                print(f"{qid} kolom {k}:\n    acuan  : {acuan[k]!r}\n    punyamu: {q.get(k)!r}")